CREATE TABLE [dbo].[RepSpecialDialingResults](	  [date] DATETIME NOT NULL	, [campaignId] SMALLINT NOT NULL	, [campaign] VARCHAR(40) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [statusCallId] INT NOT NULL	, [statusCall] VARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [statusCall_Count] VARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Count] INT NOT NULL	, [statusCall_avg] VARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [avg] DECIMAL(10,2) NULL	, [year] INT NOT NULL	, [month] INT NOT NULL	, [day] INT NOT NULL	, [hour] INT NOT NULL	, [minutes] INT NOT NULL)